using System.Collections;
using System.IO;
using System.Linq;
using AllAboard.Train;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
namespace AllAboard.Movement.Tests
{
    public sealed class PassengerFreightTests
    {
        private Scene scene;private ProceduralRailway world;private TrainDayEconomy service;
        [UnitySetUp] public IEnumerator Setup(){yield return UnityEditor.SceneManagement.EditorSceneManager.LoadSceneAsyncInPlayMode("Assets/Movement/Scenes/ProceduralRailwayPlayground.unity",new LoadSceneParameters(LoadSceneMode.Additive));yield return null;scene=SceneManager.GetSceneByPath("Assets/Movement/Scenes/ProceduralRailwayPlayground.unity");world=scene.GetRootGameObjects().Select(o=>o.GetComponent<ProceduralRailway>()).First(w=>w!=null);service=world.Train.GetComponent<TrainDayEconomy>();}
        [UnityTearDown] public IEnumerator Cleanup(){if(scene.IsValid()&&scene.isLoaded)yield return SceneManager.UnloadSceneAsync(scene);}
        [Test] public void QueueBoardingRespectsCapacityAndNeverDuplicatesTickets(){Assert.That(service.BoardWaiting("Redfort"),Is.EqualTo(2));Assert.That(service.ActiveCount,Is.EqualTo(16));Assert.That(service.BoardWaiting("Redfort"),Is.Zero);Assert.That(service.Passengers.Select(p=>p.transform.parent).Distinct().Count(),Is.EqualTo(16));}
        [Test] public void IsolatedStopsHaveNoDeparturesAndDestinationsAreReachable(){foreach(var pair in service.Queues){Assert.That(world.Network.Node(pair.Key).place,Is.Not.EqualTo(RoutePlace.Station));foreach(var p in pair.Value)Assert.That(PassengerSchedule.Reachable(world.Network,pair.Key,p.Destination),Is.True);}}
        [Test] public void MissingDestinationFallsBackToOnlyOneHundredAtCapital(){var p=service.Passengers.First();int before=service.Wallet.Gold;Assert.That(service.Resolve(p,PassengerOutcome.Delivered,true),Is.EqualTo(100));Assert.That(service.Resolve(p,PassengerOutcome.Delivered,true),Is.Zero);Assert.That(service.Wallet.Gold,Is.EqualTo(before+100));}
        [Test] public void RoughDrivingCreatesUnhappyPassengersWhoLeaveWithoutPay(){var p=service.Passengers.First();p.Step(60,3,1,false);Assert.That(p.WantsToLeave,Is.True);Assert.That(service.Resolve(p,PassengerOutcome.HappinessLost),Is.Zero);}
        [Test] public void AcceptedFreightCreatesPhysicalCrateAndFailureIsChargedOnce(){var offer=service.Cargo.Offers.First(o=>o.origin=="Redfort");Assert.That(service.Cargo.Accept(offer),Is.True);Assert.That(offer.crate.GetComponent<PickupObject>(),Is.Not.Null);Assert.That(service.Cargo.Accept(offer),Is.False);service.Cargo.Fail(offer);service.Cargo.Fail(offer);Assert.That(service.Wallet.Obligations,Is.EqualTo(Mathf.RoundToInt(offer.reward*service.Wallet.Config.contractPenaltyFraction)));}
        [Test] public void DeliveryRequiresCorrectStopAndPhysicalDeskProximity(){var offer=service.Cargo.Offers.First(o=>o.origin=="Redfort");service.Cargo.Accept(offer);Assert.That(service.Cargo.Deliver(offer,null,offer.crate.transform.position),Is.False);world.Train.Configure(world.Path,world.Train.Cars.ToArray(),world.NodeDistance(offer.destination));world.Train.Braking=true;Vector3 desk=world.Network.Node(offer.destination).position+new Vector3(13.85f,2.25f,-5.75f);Assert.That(service.Cargo.Deliver(offer,null,desk),Is.False);offer.crate.transform.position=desk;int gold=service.Wallet.Gold;Assert.That(service.Cargo.Deliver(offer,null,desk),Is.True);Assert.That(service.Cargo.Deliver(offer,null,desk),Is.False);Assert.That(service.Wallet.Gold,Is.EqualTo(gold+offer.reward));}
        [Test] public void DamagedFreightPaysSeventyFivePercent(){var offer=service.Cargo.Offers.First(o=>o.origin=="Redfort");service.Cargo.Accept(offer);offer.crate.Damage(10);world.Train.Configure(world.Path,world.Train.Cars.ToArray(),world.NodeDistance(offer.destination));int gold=service.Wallet.Gold;Assert.That(service.Cargo.Deliver(offer,null,offer.crate.transform.position),Is.True);Assert.That(service.Wallet.Gold,Is.EqualTo(gold+Mathf.RoundToInt(offer.reward*.75f)));}
        [Test] public void ProgressRoundTripsAndInvalidPrimaryUsesBackup(){string path=Path.Combine(Path.GetTempPath(),"all-aboard-test-"+System.Guid.NewGuid()+".json");try{RunProgressStore.Save(path,new RunProgress{nextDay=2,blumt=320,repairDebt=25});RunProgressStore.Save(path,new RunProgress{nextDay=3,blumt=400});Assert.That(RunProgressStore.Load(path).nextDay,Is.EqualTo(3));File.WriteAllText(path,"{}");Assert.That(RunProgressStore.Load(path).nextDay,Is.EqualTo(2));}finally{RunProgressStore.NewRun(path);}}
        [Test] public void VillageRoadsHaveStationMarketAndHouseLinksWithoutCrossingRails(){var root=new GameObject("Village Roads Test");var material=new Material(Shader.Find("Universal Render Pipeline/Lit"));try{var m=Enumerable.Repeat(material,10).ToArray();VillageRoads.Build(root.transform,material,m,SettlementKind.Frontier);VillageRoads.HouseLane(root.transform,new Vector3(27,0,-35),-1,material,m);Assert.That(root.transform.Find("Station Village Road"),Is.Not.Null);Assert.That(root.transform.Find("Marketplace Lane"),Is.Not.Null);Assert.That(root.transform.Find("House Entry Lane"),Is.Not.Null);foreach(var filter in root.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<GeneratedRailMesh>()!=null))Assert.That(filter.sharedMesh.vertices.Min(v=>v.x),Is.GreaterThan(3));}finally{Object.DestroyImmediate(root);Object.DestroyImmediate(material);}}
    }
}
